B='https://learn.microsoft.com/en-us/'
def S(id,cat,t,p,l,part,nav,st,v,rb,ts,d,cmd=(),sec='',prod=''):
    r=dict(id=id,cat=cat,t=t,p=p,l=l,part=part,nav=nav.split('>'),st=st.split('|'),v=v.split('|'),rb=rb.split('|'),ts=ts.split('|'),d=[B+(x if x.startswith(('entra/','azure/')) else 'azure/'+x) for x in d.split()],cmd=list(cmd))
    if sec:r['sec']=sec.split('|')
    if prod:r['prod']=prod.split('|')
    return r
